# Reconstruct the recorded evidence only. Does not send input or load RimWorld code.
$ErrorActionPreference='Stop'
$project=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$runtime=Join-Path $project '.local-research/runtime'
$dir=Join-Path $project 'docs/research/rimworld/evidence'
$utf8=[Text.UTF8Encoding]::new($false)
$reader=Join-Path $PSScriptRoot 'read-biomes-runtime-save.ps1'
$snapshots=@(foreach($name in @('stonecutting-final','biomes-final','biomes-confirm-paused','biomes-stopped-a','biomes-stopped-b')){$rel=".local-research/runtime/profile-20261102/Saves/$name.rws";[ordered]@{name=$name;path=$rel;save=(& $reader -SavePath (Join-Path $project $rel)|ConvertFrom-Json)}})
Add-Type -AssemblyName System.Drawing
$specs=@(
 @('desert-mountain','biomes-005-terrain-desert.png',0,660,450,750,'Desert, Mountainous, tile282619 layer0; full terrain and climate panel.'),
 @('temperate-flat','biomes-006-green-flat.png',0,660,450,750,'Temperate forest, Flat, tile99363 layer0; full terrain and climate panel.'),
 @('boreal-flat','biomes-010-taiga.png',0,660,450,750,'Boreal forest, Flat, tile111646 layer0; full terrain and climate panel.'),
 @('desert-impassable','biomes-011-hill-sample.png',0,660,450,750,'Desert, Impassable, tile118124 layer0; movement difficulty row not displayed.'),
 @('desert-creek','biomes-014-hills-terrain.png',0,660,450,750,'Desert, Mountainous with Creek, tile176455 layer0.'),
 @('planet','biomes-012-planet.png',0,1050,450,360,'Planet GK-348 Media; Seed whip; Coverage50%.'),
 @('overview','biomes-009-north.png',440,0,1850,1200,'Observed original world-map geography after zooming and panning north.'),
 @('final-paused','biomes-stopped-b-return.png',1800,920,760,520,'Final colony view after Space pause and two equal-tick confirmation saves; medical alerts reflect unintended earlier clock advance.')
)
$shots=@()
foreach($row in $specs){
 $source=Join-Path $runtime $row[1];$relative="runtime/biomes-$($row[0]).png";$destination=Join-Path $dir $relative
 $bmp=[Drawing.Bitmap]::new($source)
 try{$crop=$bmp.Clone([Drawing.Rectangle]::new($row[2],$row[3],$row[4],$row[5]),$bmp.PixelFormat);try{$crop.Save($destination,[Drawing.Imaging.ImageFormat]::Png)}finally{$crop.Dispose()}}finally{$bmp.Dispose()}
 $capture=Get-Content -LiteralPath ($source+'.jsonl')|Select-Object -Last 1|ConvertFrom-Json
 $shots += [ordered]@{id=$row[0];image=$relative;sha256=(Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash.ToLowerInvariant();source_file=".local-research/runtime/$($row[1])";source_sha256=(Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash.ToLowerInvariant();source_size=@(2560,1440);crop_xywh=@($row[2],$row[3],$row[4],$row[5]);observed_utc=$capture.timestamp_utc;observation=$row[6]}
}
$actions=@(Get-ChildItem -LiteralPath $runtime -Filter 'biomes-*.png.actions.jsonl'|ForEach-Object{Get-Content -LiteralPath $_.FullName|ForEach-Object{[ordered]@{kind='guarded-ui-input';data=($_|ConvertFrom-Json)}}}|Sort-Object {$_.data.started_utc})
$actionPath=Join-Path $dir 'native-biomes-actions.jsonl'
[IO.File]::WriteAllText($actionPath,(($actions|ForEach-Object{ConvertTo-Json $_ -Depth 10 -Compress}) -join "`n")+"`n",$utf8)
