 @{id=176455;layer=0;shot='desert-creek';biome='Desert';terrain='Mountainous';coordinates='41.61 N, 11.76 E';movement_difficulty=4.1;movement_difficulty_displayed=$true;stones=@('Sandstone','limestone','slate');elevation_m=307;features='Mountain, caves, creek';river_displayed=$true;river='Creek';temperature_c=7.9;temperature_range_c=@(-11,27);growing_days=30;growing_period='6th of Aprimay - 6th of Septober';rainfall_mm=506;forage_percent=25;forage_food='agave fruit';graze_now=$true;disease_per_year=0.7;time_zone=1}
)
$record=[ordered]@{
 schema_version=1;evidence_id='RW17-NATIVE-BIOMES-RUNTIME';version_text='1.7.4980 rev60';assembly_sha256='eff7d97949f919fb2b151ebfb906e9be749b63410b7dbda78eeebb7972b245c3';process_id=29920;executable='F:/SteamLibrary/steamapps/common/RimWorld/RimWorld.exe';assembly_path='F:/SteamLibrary/steamapps/common/RimWorld/Assembly-CSharp.dll';profile='.local-research/runtime/profile-20261102';active_mods=@('ludeon.rimworld','ludeon.rimworld.odyssey')
 method='Foreground original-world UI tile selection and visual transcription; readonly existing-save world metadata cross-check. No new world generation or game assembly execution.'
 ui_planet=@{name='GK-348 Media';seed='whip';coverage_percent=50;screenshot='planet'};tile_observation_source='Manual visual transcription of original Terrain UI; tile IDs visible because developer mode was already enabled.';tiles=$tiles;snapshots=$snapshots
 clock=@{before_tick=$snapshots[0].save.tick;first_end_tick=$snapshots[1].save.tick;failed_confirmation_tick=$snapshots[2].save.tick;stopped_a_tick=$snapshots[3].save.tick;stopped_b_tick=$snapshots[4].save.tick;total_advanced_ticks=$snapshots[4].save.tick-$snapshots[0].save.tick;entire_session_paused=$false;final_pause_verified_by_equal_saves=($snapshots[3].save.tick -eq $snapshots[4].save.tick);cause='Redundant pause-button click after returning to an already-paused colony toggled time on; initial final/confirm filenames were not proof of pause. Space was then used and two successive saves had equal ticks.'}
 outcomes=@{desert_observed=$true;temperate_forest_observed=$true;boreal_forest_observed=$true;flat_observed=$true;mountainous_observed=$true;impassable_observed=$true;small_or_large_hills_observed=$false;new_world_parameters_ui_opened=$false;new_world_generated=$false;seed_per_tile_equivalence_demonstrated=$false;noise_function_equivalence_demonstrated=$false;local_map_generation_demonstrated=$false;world_info_and_grid_unchanged=(@($snapshots|Where-Object {$_.save.world_grid_xml_sha256 -ne $snapshots[0].save.world_grid_xml_sha256 -or $_.save.world_info_xml_sha256 -ne $snapshots[0].save.world_info_xml_sha256}).Count -eq 0)}
 screenshots=$shots;actions=@{file='native-biomes-actions.jsonl';sha256=(Get-FileHash -LiteralPath $actionPath -Algorithm SHA256).Hash.ToLowerInvariant();count=$actions.Count}
 limitations=@('This is a single existing world and five selected land tiles, not a statistical biome survey or regeneration comparison.','Screenshots establish UI fields and observations only. They do not prove noise implementation, same-seed regeneration, or matching native local-map tiles.','The installed world is Core + Odyssey. Developer mode and God mode were already enabled; no developer generation button was used.','The first click selected an ocean tile; it is retained in the ledger but not presented as a land-biome sample.','Small hills and Large hills were not observed; the extra candidates were Mountainous and Impassable.','Absent UI rows are recorded as not displayed rather than proofs that the underlying value or feature cannot exist. Tile arrays in saves were not decoded.','The end-of-session pause was initially mishandled; the isolated colony advanced83122 ticks, developed medical alerts, and was finally paused at134003. Original stonecutting-final was not overwritten and remains recoverable.','World metadata and serialized world grid hashes stayed identical across all five saves; pawn/colony simulation state did change during the accidental advance.','Portable verification checks record integrity, UI transcription consistency and evidence hashes; local mode re-reads original saves/captures. Neither performs OCR or reruns the game.')
 final_state=@{paused=$true;pause_confirmed_by_two_equal_saves=$true;canonical_save='biomes-stopped-b.rws';original_stonecutting_save_untouched=$true;research_colony_simulation_changed=$true;normal_profile_touched=$false;game_files_modified=$false;mods_installed=$false;developer_mode=$true;god_mode=$true}
}
[IO.File]::WriteAllText((Join-Path $dir 'native-biomes-runtime.json'),(ConvertTo-Json $record -Depth 24)+"`n",$utf8)
"Collected $($tiles.Count) tile observations, $($snapshots.Count) save snapshots, $($shots.Count) crops, $($actions.Count) UI actions. Final tick $($snapshots[4].save.tick)."
